mapper.select:
select fpd.finprod_id finprodId, fpd.finprod_abbr finprodAbbr, fpd.finprod_name finprodName, fpd.FINPROD_TYPE finprodType, fpd.profit_type profitType, fpd.p_Finprod_Id pFinprodId, pfpd.finprod_name pFinprodName, /* 挂钩母产品 名称 */ basi.acct_subject_name acctSubjectName, /* 投资组合 名称 */ fpd.issue_price issuePrice, fpd.issue_amt issueAmt, fpd.issue_Type issueType, fpd.CCY ccyCode, fpd.CCY ccy, fpd.REGIST_ORG registOrg, /*托管机构 */ crule.yield * 100 yield, /*预期收益率*/ '' investType, '' raiseType, to_char(fpd.VDATE, 'yyyy-MM-dd') vdate, to_char(fpd.MDATE, 'yyyy-MM-dd') mdate, to_char(fpd.iDATE, 'yyyy-MM-dd') idate, to_char(fpd.actmdate, 'yyyy-MM-dd') actmdate, fpd.MDATE - fpd.vDATE term, 'A/365' basis, ext.sale_period salePeriod, case when nvl(ext.sale_layer, 0) != 0 then 'Y' else 'N' end isSaleLayer, ext.profit_flag prdIncomeType, ext.profit_flag prdIncomeTypeCode, decode(ext.IS_RECONCILIATION, 'Y', 'true', 'false') isReconciliation, fpd.o_Finprod_Id oFinprodId, fpd.is_chl isChl, fpd.is_sus isSus, fpd.is_right isRight, amt.trade_amt planraiseAmt, decode(bbext.PARAM_VALUE, 'Y', 'true', 'false') isTrustCurrent, fpd.CALENDAR_ID AS calendarId, C.CALENDAR_NAME AS calendarName from FIN_PRODUCT fpd left join (select a.* from fin_cash_calc_rule a left join FIN_CASH_INFO b on a.cash_id = b.cash_id where b.CASH_TYPE_2 = 'C02') crule on crule.EFF_DATE = fpd.VDATE and crule.FINPROD_ID = fpd.FINPROD_ID and crule.FINPROD_TYPE = fpd.FINPROD_TYPE left join FIN_PRODUCT pfpd on pfpd.finprod_id = fpd.p_finprod_id left join FIN_PRODUCT_ADD ext on fpd.finprod_id = ext.finprod_id /*and fpd.finprod_type = ext.finprod_type*/ /*产品信息查询募集金额查询不到bug修改*/ left join BOK_ACCT_SUBJECT_INFO basi on basi.acct_subject_id = ext.portfolio_id left join (select sum(tpd.trade_amt) trade_amt, tpd.finprod_id, tpd.settle_date, tpd.finprod_type from TRD_PRODUCT_DEAL tpd group by tpd.finprod_id, tpd.settle_date, tpd.finprod_type) amt on fpd.finprod_id = amt.finprod_id and amt.settle_date = fpd.VDATE and amt.finprod_type = fpd.finprod_type LEFT JOIN MST_CALENDAR_INFO C ON C.CALENDAR_ID = fpd.CALENDAR_ID LEFT JOIN BOK_BOOKSET_EXT bbext ON bbext.BOOKSET_ID = fpd.finprod_id AND bbext.PARAM_CODE = 'PRD_IS_CALC' where 1=1
AND fpd.FINPROD_TYPE = #{finprodType}
AND fpd.profit_Type in
#{profitType}
AND fpd.OPERATION_TYPE in
#{operationType}
AND fpd.FINPROD_id in
#{finprodId}
AND fpd.VDATE >=to_date(#{vdateStart},'yyyy-MM-dd')
AND fpd.VDATE <=to_date(#{vdateEnd},'yyyy-MM-dd')
AND fpd.mDATE >=to_date(#{mdateStart},'yyyy-MM-dd')
AND fpd.mDATE <=to_date(#{mdateEnd},'yyyy-MM-dd')
order by fpd.VDATE desc,fpd.profit_type

WITH tmp AS ( SELECT CASH_ID, ACCR_TDAY_RULE from FIN_FLOAT_COUNTING_RULE GROUP BY CASH_ID, ACCR_TDAY_RULE ) SELECT * FROM ( SELECT info.cash_id cashId,/*现金流代码*/ fpt.finprod_abbr finprodAbbr,/*金融产品简称*/ info.finprod_id finprodId,/*金融产品代码*/ info.finprod_type finprodType,/*金融产品类型*/ info.cash_type_1 cashType1,/*现金流一级类型，本金、利息、费用 */ info.cash_type_1 cashType1Code,/*现金流一级类型，本金、利息、费用 */ info.cash_type_2 cashType2,/*现金流二级类型，本金、利息、托管费、固定管理费、浮动管理费等 */ info.cash_type_2 cashType2Code,/*现金流二级类型，本金、利息、托管费、固定管理费、浮动管理费等 */ to_char(ffcr.f_accr_date, 'yyyy-MM-dd') effDate,/*生效日期 */ crule.calc_type calcType,/*计算类型，固定利率、浮动利率 */ crule.calc_type calcTypeCode,/*计算类型，固定利率、浮动利率 */ crule.yield * 100 yield,/*生效利率 */ crule.basis,/*计息基础，a/360，a/365等 */ crule.base_type baseType,/*基数类型 */ crule.base_type baseTypeCode,/*基数类型 */ crule.base_date_type baseDateType,/*基数日期类型，上一工作日、上一自然日、当日、上一开放日等 */ crule.base_date_type baseDateTypeCode,/*基数日期类型，上一工作日、上一自然日、当日、上一开放日等 */ prule.pay_cycle payCycle,/*支付频率 */ prule.pay_cycle payCycleCode,/*支付频率 */ prule.END_TDAY_RULE endTdayRule, /*付费截止日营业日准则 */ prule.END_TDAY_RULE endTdayRuleCode, /*付费截止日营业日准则 code*/ prule.PAY_TDAY_RULE payTdayRule, /*付费支付日营业日准则 */ prule.PAY_TDAY_RULE payTdayRuleCode, /*付费支付日营业日准则 code*/ prule.calc_rule calcRule,/*推算方式 */ prule.calc_rule calcRuleCode,/*推算方式 */ to_char(prule.first_pay_date, 'yyyy-MM-dd') firstPayDate,/*首次支付日 */ prule.cash_unit_type cashUnitType,/*现金流单位，百元法、总额法 */ prule.cash_unit_type cashUnitTypeCode,/*现金流单位，百元法、总额法 */ prule.pay_type payType, /*支付方式，现金、红利再投等 */ prule.pay_type payTypeCode, /*支付方式，现金、红利再投等 */ crule.remark, A.ACCR_TDAY_RULE as accrTdayRule,/** 计费营业日准则 **/ ROW_NUMBER() OVER( PARTITION BY crule.CASH_ID, crule.FINPROD_ID, crule.FINPROD_TYPE ORDER BY crule.EFF_DATE ASC) AS rn1, ROW_NUMBER() OVER( PARTITION BY prule.CASH_ID, prule.FINPROD_ID, prule.FINPROD_TYPE ORDER BY crule.EFF_DATE ASC) AS rn2 FROM FIN_CASH_INFO info LEFT JOIN fin_product fpt ON info.finprod_id = fpt.finprod_id LEFT JOIN fin_cash_calc_rule crule ON info.cash_id = crule.cash_id AND info.finprod_id = crule.finprod_id AND info.finprod_type = crule.finprod_type LEFT JOIN fin_cash_pay_rule prule ON info.cash_id = prule.cash_id AND info.finprod_id = prule.finprod_id AND info.finprod_type = prule.finprod_type LEFT JOIN Fin_Float_Counting_Rule ffcr ON crule.cash_id = ffcr.cash_id AND crule.eff_date = ffcr.eff_date LEFT JOIN tmp A ON A.CASH_ID = info.CASH_ID WHERE info.cash_type_1 = '03'
AND info.FINPROD_id = #{finprodId}
AND info.cash_type_2 = #{cashType2}
AND info.cash_type_2 != #{noCashType2}
) WHERE rn1 = 1 AND rn2 = 1

select info.acct_no acctNo, info.acct_name acctName, info.acct_name acctName1, info.busi_acct_no busiAcctNo, info.ccy ccy, info.in_out_bank inOutBank, info.bank_dep bankDep, info.corr_no corrNo, info.large_payno largePayno, info.swift_code swiftCode, info.remark remark, acct.acct_type acctType, acct.finprod_id finprodId, acct.finprod_type finprodType, '' bankDepType, '' customerName from Stl_Fin_Product_Acct acct left join stl_capacct_info info on acct.acct_no = info.acct_no where 1=1
AND acct.FINPROD_TYPE = #{finprodType}
AND acct.FINPROD_ID = #{finprodId}
AND info.ACCT_NAME = #{acctName}

select ffcr2.ACT_RULE actRule, /*生效规则 */ ffcr2.base_type baseType, /*计费基数 */ ffcr2.AST_VDATE_TYPE actVdateType, /*资产净值日 */ TO_CHAR(ffcr.f_accr_date, 'yyyy-MM-dd') firCalculaDate, /*首次计提日*/ TO_CHAR(ffcr.e_accr_date, 'yyyy-MM-dd') endCalculaDate, /*计提结束日 */ ffcr.ACCR_CYCLE_UNIT accrCycle /*计提频率*/ from fin_cash_info fci left join fin_float_counting_rule ffcr on fci.cash_id = ffcr.cash_id left join fin_float_calc_rule ffcr2 on ffcr2.cash_id = ffcr.cash_id where 1=1
AND fci.finprod_id= #{finprodId}
AND fci.cash_type_2 = #{cashType2}

select TO_CHAR(ffas.accr_str_date, 'yyyy-MM-dd') jtStrDate, /*计提周期开始日 */ TO_CHAR(ffas.accr_end_date, 'yyyy-MM-dd') jtEndDate, /*计提周期结束日 */ TO_CHAR(ffas.accr_date, 'yyyy-MM-dd') jtDate /*计提日 */ from fin_cash_info fci LEFT JOIN FIN_FLOAT_ACCRUAL_SCHE ffas ON ffas.cash_id = fci.cash_id where 1=1
AND fci.finprod_id= #{finprodId}
AND fci.cash_type_2 = #{cashType2}
order by ffas.accr_str_date asc

select C.LEV AS basicLevel, /*业绩比较基准层级 */ C.BASE_RULE_ID AS baseRuleId, /*业绩基准 */ C.COEFFICIENT AS coefficient, /*调整系数 */ C.SPREAD_RATE AS spread, /*利差 */ C.CHARGE_RATIO * 100 AS bankRatio /*银行收取比例 */ from fin_cash_info fci LEFT JOIN ( SELECT CASH_ID,MAX(EFF_DATE) MAX_EFF_DATE FROM FIN_FLOAT_CALC_RULE GROUP BY CASH_ID ) TMP ON TMP.CASH_ID = fci.CASH_ID LEFT JOIN FIN_FLOAT_CALC_RULE_DETAIL C ON C.CASH_ID = TMP.CASH_ID AND C.EFF_DATE = TMP.MAX_EFF_DATE where 1=1
AND fci.finprod_id= #{finprodId}
AND fci.cash_type_2 = #{cashType2}
order by C.LEV asc

SELECT finprodId, /*产品代码*/ acctId, /*编号（内部ID）*/ acctCode, /*账户名称*/ brokerName, /*所属券商*/ acctDesc, /*账户描述*/ COUNT(*) bankDescnumb /*关联资金账户*/ FROM ( SELECT JPH.SHORTCODE finprodId, --产品代码 JS.ACCTID acctId,--编号（内部ID） JS.ACCTCODE acctCode, --账户名称 JB.BROKERNAME brokerName, --所属券商 JS.ACCTDESC acctDesc,--账户描述 JBCA.BANKDESC bankDesc --关联资金账户 FROM JXB_SECACCT JS JOIN JXS_PORTFOLIO_HDR JPH ON JPH.PORTFOLIO = JS.PORTFOLIO JOIN JXS_BROKER JB ON JB.BROKERID = JS.BROKERCODE JOIN JXB_BK_CASH_ACCT JBCA ON JBCA.BK_ACCT_NO = JS.DEFAULTCASHACCT WHERE 1=1
AND JPH.SHORTCODE = #{finprodId}
) GROUP BY finprodId, acctId, acctCode, brokerName, acctDesc

select fci.cash_id as cashId
    from FIN_CASH_INFO fci
where fci.cash_id = #{cashId}

select ffas.cash_id as cashId, ffas.accr_date as jtDate
    from Fin_Float_Accrual_Sche ffas
where ffas.cash_id = #{cashId}
    and to_char(ffas.accr_date, 'yyyy-MM-dd') = #{jtDate}

select sfpa.finprod_id as finprodId, sfpa.acct_no as acctNo, sfpa.acct_type as acctType
    from Stl_Fin_Product_Acct sfpa
where sfpa.finprod_id = #{finprodId}
    and sfpa.acct_no = #{acctNo}
    and sfpa.acct_type = #{acctType}

select fccr.cash_id as cashId
    from FIN_CASH_CALC_RULE fccr
where fccr.cash_id = #{cashId}
and to_char(fccr.eff_date, 'yyyy-MM-dd') = #{effDate}
